"""Supervised single-Issue landing. The provider adapter never runs in candidate code."""
import contextlib
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import shlex
import sys
import subprocess
import tempfile

from soodles import Refusal, checked, clean_env, runtime_check, source_identity

REPOSITORY = "ed3c/soodles"
ACTION = "./soodles landing"


class LandingRefusal(Refusal):
    def __init__(self, field, value, next_action=None):
        self.invalid = {"field": field, "value": value}
        self.next_action = next_action
        super().__init__(f"landing: invalid {field}={value!r}")


def require(condition, field, value, next_action=None):
    if not condition:
        raise LandingRefusal(field, value, next_action)


def cli_argv(operation, *arguments):
    return [sys.executable, "-B", str(Path(__file__).resolve().parent / "soodles.py"),
            "landing", *([operation] if operation else []), *map(str, arguments)]


def input_next(operation, required, checkpoint=None):
    return {"kind": "input", "owner": "supervisor", "operation": operation, "required": required,
            "known": {"checkpoint": str(Path(checkpoint).resolve())} if checkpoint else {},
            "help_argv": cli_argv(operation, "--help")}


def provider_next(claim, operation, checkpoint):
    base = "https://api.github.com/repos/" + claim["repository"] + "/"
    paths = {"pr": f"pulls/{claim['pr']}", "issue": f"issues/{claim['issue']}",
             "commit": f"git/commits/{claim['head']}", "branch": "branches/main",
             "run": f"actions/runs/{claim['run_id']}", "jobs": f"actions/runs/{claim['run_id']}/jobs"}
    return {**input_next(operation, ["readback"], checkpoint), "kind": "provider_readback", "owner": "GitHub",
            "requests": {key: {"method": "GET", "url": base + path} for key, path in paths.items()},
            "merge_commit": "If pr.merged, GET git/commits/{pr.merge_commit_sha} in this repository."}


def response(operation, state, action, next_action, **details):
    return {"owner": "landing." + operation, "action": action, "phase": state["phase"],
            "classification": state.get("classification"), "next": next_action, **details}


def refusal_output(error, operation):
    # The invoked action supplies ownership; field spelling never selects a route.
    next_action = error.next_action or input_next(operation, ["corrected_input"])
    return {"owner": "landing." + operation if operation else "landing", "status": "refused",
            "invalid": error.invalid, "next": next_action}


def refusal_text(result):
    invalid = result["invalid"]
    help_argv = result["next"]["help_argv"]
    return (f"REFUSED: {result['owner']}: invalid {invalid['field']}={invalid['value']!r}; "
            f"supported help: {shlex.join(help_argv)}"
            + ("; " + result["next"]["reason"] if result["next"].get("reason") else ""))


def fingerprint(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def verifier_digest():
    # A supervisor selects this implementation outside the candidate under evaluation.
    root = Path(__file__).resolve().parent
    return fingerprint({name: hashlib.sha256((root / name).read_bytes()).hexdigest()
                        for name in ("landing.py", "soodles.py", "issue_admission.py",
                                     "issue_execution.py", "policy/runtime.lock.json")})


def advance(checkpoint, snapshot):
    with locked(checkpoint) as path:
        state = delivery_state(path)
        claim = state["claim"]
        validate_claim(claim)
        if state["phase"] == "readmission_pending" and state["recovery"].get("kind") == "amendment":
            return recovery_action(state, state["recovery"]["base_head"], path, "advance")
        recovery = observe_base(path, state, snapshot, "advance")
        if recovery:
            return recovery
        validate_snapshot(claim, snapshot, operation="advance", checkpoint=path)
        if state["phase"] == "readmission_pending":
            return recovery_action(state, state["recovery"]["base_head"], path, "advance")
        phase = state["phase"]
        if phase == "resolved":
            return response("advance", state, "stop", None)
        observation = fingerprint(snapshot)
        if observation not in state["observations"]:
            state["observations"].append(observation)
            state["observations"] = state["observations"][-8:]
        if snapshot["pr"].get("merged"):
            require("merge" in state["writes_offered"], "merge.owner", "no merge request offered by this checkpoint")
            state["merge_sha"] = snapshot["pr"]["merge_commit_sha"]
            if snapshot["issue"]["state"] == "closed":
                require("close" in state["writes_offered"], "closure.owner", "no close request offered by this checkpoint")
                state["issue_closed_at"] = snapshot["issue"]["closed_at"]
                if phase not in {"reconciling", "resolved"}:
                    state["phase"] = "awaiting_reconcile"
            elif phase == "merge_pending":
                state["phase"] = "close_pending"
                state["delivery"] = {"action": "close", "status": "prepared"}
        elif phase == "admitted":
            require(snapshot["pr"].get("mergeable") is True, "pr.mergeable", snapshot["pr"].get("mergeable"))
            state["phase"] = "merge_pending"
            state["delivery"] = {"action": "merge", "status": "prepared"}
        save(path, state)
        prepared = state["phase"] in {"merge_pending", "close_pending"} and state["delivery"]["status"] == "prepared"
        if prepared:
            return response("advance", state, "dispatch", provider_next(claim, "dispatch", path))
        if state["phase"] in {"awaiting_reconcile", "reconciling"}:
            return response("advance", state, "reconcile", input_next("reconcile", ["binary"], path))
        return response("advance", state, "readback", provider_next(claim, "advance", path))


def dispatch(checkpoint, snapshot):
    """Consume one prepared intent for the supervisor's existing connector transport."""
    with locked(checkpoint) as path:
        state = delivery_state(path)
        claim = state["claim"]
        validate_claim(claim)
        require(state["phase"] != "readmission_pending", "dispatch.phase",
                state["phase"], input_next("readmit", ["claim", "readback"], path))
        recovery = observe_base(path, state, snapshot, "dispatch")
        if recovery:
            return recovery
        validate_snapshot(claim, snapshot, operation="dispatch", checkpoint=path)
        require(state["phase"] in {"merge_pending", "close_pending"}, "dispatch.phase", state["phase"])
        delivery = state["delivery"]
        require(delivery["status"] == "prepared", "dispatch.status",
                delivery["status"], provider_next(claim, "advance", path))
        if delivery["action"] == "merge":
            require(not snapshot["pr"].get("merged") and snapshot["pr"].get("mergeable") is True,
                    "dispatch.pr", "merge no longer eligible", provider_next(claim, "advance", path))
            request = {"action": "merge", "repository_full_name": REPOSITORY, "pr_number": claim["pr"],
                       "expected_head_sha": claim["head"], "merge_method": "merge"}
        else:
            require(snapshot["pr"].get("merged") and snapshot["issue"]["state"] == "open",
                    "dispatch.issue", "closure no longer eligible", provider_next(claim, "advance", path))
            request = {"action": "close", "repository_full_name": REPOSITORY, "issue_number": claim["issue"],
                       "state": "closed", "state_reason": "completed"}
        delivery["status"] = "offered"
        state["writes_offered"].append(delivery["action"])
        save(path, state)  # Must precede request emission; an interrupted offer remains unknown.
        return response("dispatch", state, request["action"], provider_next(claim, "advance", path), request=request)


## LANDING.SUPERVISED.001

Owner: ed3c/soodles#4. `landing.py` and `tests/test_landing.py` own this boundary. The supervisor selects a verifier implementation outside the candidate and pins its SHA-256 in an exact single-Issue claim. The claim binds repository, Issue, PR, head, tree, base head, successful runtime run/attempt, and local worktree. A digest binds bytes; the supervising session supplies initial trust. It is not a signature or an independent correctness oracle.

`landing start` rejects mismatched provider identity before admission. `landing advance` prepares an expected-head merge or exact-Issue closure intent in the checkpoint. `landing dispatch` revalidates the provider snapshot and durably consumes that intent before emitting the request once. Neither command performs provider writes. The GitHub connector is the transport in the supervised fallback. Existing GitHub rules apply; no bypass or permission mutation is offered. Raw snapshots are trusted only as provider readbacks transported by that supervisor, never as candidate-supplied evidence.

Merged state must agree with the expected parent pair and candidate tree before closure can be offered. A completed Issue readback permits `landing reconcile`: validate local origin/clean source/exact candidate, fast-forward main, ask Noodle to remove the worktree, then read back main and worktree/branch absence. Only this writes classification RESOLVED. Interrupted reconciliation can resume from its persisted intent; dirty or divergent local state refuses before cleanup. Retained other worktrees belong to their own admitted Issues.

There is at most one merge request and one closure request per checkpoint, no automatic retries, and no polling loop. Pending unknown outcomes remain pending for owner-specific readback. No production generation closure, autonomous scheduling, crash-safe remote transaction, or independent default-branch verification is claimed. The supervisor must not delete/recreate a checkpoint to repeat an unknown write.

After provider closure, a corrected verifier can resume an interrupted reconciliation through `landing resume`: only the verifier digest may change under a fresh supervisor claim; preserve prior digest and all provider/local identities and write intents. This emits no provider write. The real bootstrap reconciliation exposed missing proxy transport in the fixture-only environment; network fetch therefore retains standard proxy variables while excluding provider credentials and Git environment overrides.
### Owner next-action output — ed3c/soodles#21

`landing.py` owns the `next` projection. Every transition response names the invoked owner, action, phase, classification and next step. A provider readback names GET operations against the admitted repository/Issue/PR/head/run; missing inputs and the resumed operation are explicit. A local input step names the supervisor, required inputs, known checkpoint and structured executable help argv. It never invents a readback path, binary, claim or authority. RESOLVED yields action=stop and next=null without rewriting the checkpoint. These fields are returned projections, not another durable state machine.

The existing connector write payload remains exact inside `request`; transport must consume that payload only. Dispatch persists its offered intent before returning it. All existing head/readback/phase/write guards still execute when the command runs; a previously printed next step confers no execution authority. Prepared delivery requires fresh provider readback; unknown offers lead only to owner readback. Awaiting or interrupted reconciliation names its missing binary input rather than requesting indefinite provider polling.

Structured refusals and human diagnostics derive from one invalid field/value and next action. The actually invoked CLI verb owns the refusal, rather than a substring of the invalid field. Explicit transition refusals can name a different legal recovery operation, with one help route. Parser/input failures are structured too. Old checkpoint schemas retain their existing interpretation; displayed next commands are never used as migration or retry authority.

`delivery_oracle.py` is the nearest standalone CLI/process observer. Alongside existing SIGKILL, concurrent dispatch and lost-response controls, it rejects conflicting next operations and terminal readback output. Its terminal checkpoint is explicitly a fixture, not a live reconciliation claim. Candidate copies remain non-authorizing; supervisor-selected external bytes judge baseline/treatment/planted regression. Existing base-recovery consumers read the same structured projection and unchanged nested connector payload.

